-- E5-DB1 extended this boundary: the company timeline now returns
-- `visibility = 'company'` only. The restricted fixtures below are deliberately
-- NEWER than every company row, so a regression in the predicate would not just
-- add a row — it would break the ordering and limit assertions too.
begin; create extension if not exists pgtap with schema extensions; set local search_path=extensions,public,pg_temp; select plan(24);
select has_function('public','get_tenant_activity_timeline_v1',array['uuid','integer']); select is((select prosecdef from pg_proc where oid='public.get_tenant_activity_timeline_v1(uuid,integer)'::regprocedure),true,'SECURITY DEFINER'); select is((select provolatile from pg_proc where oid='public.get_tenant_activity_timeline_v1(uuid,integer)'::regprocedure),'s'::"char",'STABLE'); select is((select proconfig from pg_proc where oid='public.get_tenant_activity_timeline_v1(uuid,integer)'::regprocedure),array['search_path=public, pg_temp']::text[],'search path hardened'); select is((select pg_get_userbyid(proowner) from pg_proc where oid='public.get_tenant_activity_timeline_v1(uuid,integer)'::regprocedure),'postgres','owner postgres');
select ok(has_function_privilege('authenticated','public.get_tenant_activity_timeline_v1(uuid,integer)','execute'),'authenticated execute'); select ok(not has_function_privilege('public','public.get_tenant_activity_timeline_v1(uuid,integer)','execute'),'PUBLIC denied'); select ok(not has_function_privilege('anon','public.get_tenant_activity_timeline_v1(uuid,integer)','execute'),'anon denied'); select ok(not has_function_privilege('service_role','public.get_tenant_activity_timeline_v1(uuid,integer)','execute'),'service role denied'); select ok(not has_table_privilege('authenticated','public.activity_events','select'),'table remains closed');
select is((select proargnames from pg_proc where oid='public.get_tenant_activity_timeline_v1(uuid,integer)'::regprocedure),array['p_company_id','p_limit','activity_id','activity_type','module','title','description','actor_type','actor_id','entity_type','entity_id','subject_type','subject_id','visibility','metadata','occurred_at','created_at']::text[],'exact contract'); select is((select pg_get_expr(proargdefaults,0) from pg_proc where oid='public.get_tenant_activity_timeline_v1(uuid,integer)'::regprocedure),'20','default limit 20');
insert into auth.users(id,email) values('84040000-0000-4000-8000-000000000001','act-owner@example.com'),('84040000-0000-4000-8000-000000000002','act-inactive@example.com'); insert into public.companies(id,name,slug) values('84040000-0000-4000-8000-000000000101','Act A','act-a'),('84040000-0000-4000-8000-000000000102','Act B','act-b'); insert into public.company_members(id,company_id,user_id,role,status) values('84040000-0000-4000-8000-000000000111','84040000-0000-4000-8000-000000000101','84040000-0000-4000-8000-000000000001','owner','active'),('84040000-0000-4000-8000-000000000112','84040000-0000-4000-8000-000000000101','84040000-0000-4000-8000-000000000002','employee','inactive'); insert into public.activity_events(id,company_id,activity_type,module,title,occurred_at) values('84040000-0000-4000-8000-000000000201','84040000-0000-4000-8000-000000000101','test.old','test','Old','2026-01-01'),('84040000-0000-4000-8000-000000000202','84040000-0000-4000-8000-000000000101','test.new','test','New','2026-01-02'),('84040000-0000-4000-8000-000000000203','84040000-0000-4000-8000-000000000102','test.foreign','test','Foreign','2026-01-03');
-- Restricted rows, newest of all: one generic, one shaped exactly like the audit
-- the Feedback boundary writes.
insert into public.activity_events(id,company_id,activity_type,module,title,entity_type,entity_id,visibility,metadata,occurred_at) values('84040000-0000-4000-8000-000000000204','84040000-0000-4000-8000-000000000101','admin.secret','people','Restrito',null,null,'restricted','{}','2026-01-04'),('84040000-0000-4000-8000-000000000205','84040000-0000-4000-8000-000000000101','feedback.created','feedback','Feedback criado','feedback_thread','84040000-0000-4000-8000-000000000301','restricted','{"operation": "create"}','2026-01-05');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"84040000-0000-4000-8000-000000000001","role":"authenticated"}',true); select is((select count(*) from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',1)),1::bigint,'limit applied'); select is((select title from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',1)),'New','newest COMPANY row first, restricted never outranks it'); select ok(not exists(select 1 from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',20) where title='Foreign'),'cross tenant absent'); select throws_ok($$select * from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',0)$$,'22023','ACTIVITY_LIMIT_OUT_OF_RANGE','zero rejected'); select throws_ok($$select * from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',101)$$,'22023','ACTIVITY_LIMIT_OUT_OF_RANGE','excess rejected');
-- Semantics, not counts: company activity keeps working, and nothing restricted
-- reaches the tenant timeline by any route.
select ok(exists(select 1 from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',100) where title='Old'),'company activity still served'); select is((select count(*) from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',100)),2::bigint,'exactly the company rows of this tenant'); select is((select count(*) from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',100) where visibility<>'company'),0::bigint,'no restricted row of any kind'); select ok(not exists(select 1 from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',100) where title='Restrito'),'restricted administrative audit hidden'); select is((select count(*) from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',100) where module='feedback' or entity_type='feedback_thread'),0::bigint,'restricted Feedback audit never appears');
select set_config('request.jwt.claims','{"sub":"84040000-0000-4000-8000-000000000002","role":"authenticated"}',true); select throws_ok($$select * from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',20)$$,'42501','TENANT_AUTHORIZATION_DENIED','inactive denied'); reset role; select set_config('request.jwt.claims','{}',true); select throws_ok($$select * from public.get_tenant_activity_timeline_v1('84040000-0000-4000-8000-000000000101',20)$$,'42501','AUTHENTICATION_REQUIRED','auth required'); select * from finish(); rollback;
